.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/3zzPk-k4Xaw/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2020-07-10T18:00:02Z","viewCount":3852701,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
